"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([["653707"],{149366:function(e){e.exports=JSON.parse('{"tag":{"label":"Super","permalink":"/tags/super","allTagsPath":"/tags","count":4,"items":[{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Super/reComputer_Super_vs_Classic_Next-Gen_AI_Performance_in_Edge_Inferencing","title":"reComputer Super vs Classic Next-Gen AI Performance in Edge Inferencing","description":"This article highlights the superior AI performance of the reComputer Super compared to the reComputer Classic, demonstrating up to a 1.7x boost in AI compute power with the NVIDIA Jetson Orin NX 16GB. Through practical benchmarks in AI text generation using the DeepSeek-R1:7B model with Ollama, and AI video processing using the YOLOv11 object detection model, the results show that the reComputer Super delivers significantly faster inference speeds and higher GPU frequencies. Notably, it processes approximately 2.37 times more images per second than the Classic. The article also explains the importance of evaluating performance based on terminal-reported FPS rather than on-screen FPS, which can be limited by display and system factors.","permalink":"/recomputer_jetson_super_performance"},{"id":"es/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Super/es_reComputer_Super_vs_Classic_Next-Gen_AI_Performance_in_Edge_Inferencing","title":"reComputer Super vs Classic Rendimiento de IA de Nueva Generaci\xf3n en Inferencia Edge","description":"Este art\xedculo destaca el rendimiento superior de IA del reComputer Super comparado con el reComputer Classic, demostrando hasta un aumento de 1.7x en potencia de c\xf3mputo de IA con el NVIDIA Jetson Orin NX 16GB. A trav\xe9s de benchmarks pr\xe1cticos en generaci\xf3n de texto de IA usando el modelo DeepSeek-R1:7B con Ollama, y procesamiento de video de IA usando el modelo de detecci\xf3n de objetos YOLOv11, los resultados muestran que el reComputer Super ofrece velocidades de inferencia significativamente m\xe1s r\xe1pidas y frecuencias de GPU m\xe1s altas. Notablemente, procesa aproximadamente 2.37 veces m\xe1s im\xe1genes por segundo que el Classic. El art\xedculo tambi\xe9n explica la importancia de evaluar el rendimiento bas\xe1ndose en los FPS reportados por terminal en lugar de los FPS en pantalla, que pueden estar limitados por factores de pantalla y sistema.","permalink":"/es/recomputer_jetson_super_performance"},{"id":"ja/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Super/ja_reComputer_Super_vs_Classic_Next-Gen_AI_Performance_in_Edge_Inferencing","title":"reComputer Super vs Classic \u30A8\u30C3\u30B8\u63A8\u8AD6\u306B\u304A\u3051\u308B\u6B21\u4E16\u4EE3AI\u6027\u80FD","description":"\u3053\u306E\u8A18\u4E8B\u3067\u306F\u3001NVIDIA Jetson Orin NX 16GB\u3092\u4F7F\u7528\u3057\u305FreComputer Super\u3068reComputer Classic\u306E\u512A\u308C\u305FAI\u6027\u80FD\u3092\u7D39\u4ECB\u3057\u3001AI\u30B3\u30F3\u30D4\u30E5\u30FC\u30C6\u30A3\u30F3\u30B0\u30D1\u30EF\u30FC\u3067\u6700\u59271.7\u500D\u306E\u5411\u4E0A\u3092\u5B9F\u8A3C\u3057\u3066\u3044\u307E\u3059\u3002Ollama\u3067DeepSeek-R1:7B\u30E2\u30C7\u30EB\u3092\u4F7F\u7528\u3057\u305FAI\u30C6\u30AD\u30B9\u30C8\u751F\u6210\u3068\u3001YOLOv11\u7269\u4F53\u691C\u51FA\u30E2\u30C7\u30EB\u3092\u4F7F\u7528\u3057\u305FAI\u30D3\u30C7\u30AA\u51E6\u7406\u306E\u5B9F\u7528\u7684\u306A\u30D9\u30F3\u30C1\u30DE\u30FC\u30AF\u3092\u901A\u3058\u3066\u3001reComputer Super\u304C\u5927\u5E45\u306B\u9AD8\u901F\u306A\u63A8\u8AD6\u901F\u5EA6\u3068\u3088\u308A\u9AD8\u3044GPU\u5468\u6CE2\u6570\u3092\u63D0\u4F9B\u3059\u308B\u3053\u3068\u3092\u793A\u3057\u3066\u3044\u307E\u3059\u3002\u7279\u306B\u3001Classic\u3068\u6BD4\u8F03\u3057\u3066\u7D042.37\u500D\u591A\u304F\u306E\u753B\u50CF\u30921\u79D2\u9593\u306B\u51E6\u7406\u3057\u307E\u3059\u3002\u3053\u306E\u8A18\u4E8B\u3067\u306F\u3001\u30C7\u30A3\u30B9\u30D7\u30EC\u30A4\u3084\u30B7\u30B9\u30C6\u30E0\u8981\u56E0\u306B\u3088\u3063\u3066\u5236\u9650\u3055\u308C\u308B\u53EF\u80FD\u6027\u304C\u3042\u308B\u753B\u9762\u4E0A\u306EFPS\u3067\u306F\u306A\u304F\u3001\u30BF\u30FC\u30DF\u30CA\u30EB\u3067\u5831\u544A\u3055\u308C\u308BFPS\u306B\u57FA\u3065\u3044\u3066\u6027\u80FD\u3092\u8A55\u4FA1\u3059\u308B\u3053\u3068\u306E\u91CD\u8981\u6027\u306B\u3064\u3044\u3066\u3082\u8AAC\u660E\u3057\u3066\u3044\u307E\u3059\u3002","permalink":"/ja/recomputer_jetson_super_performance"},{"id":"zh-CN/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Super/cn_reComputer_Super_vs_Classic_Next-Gen_AI_Performance_in_Edge_Inferencing","title":"reComputer Super \u4E0E Classic \u7684\u4E0B\u4E00\u4EE3\u8FB9\u7F18\u63A8\u7406 AI \u6027\u80FD\u5BF9\u6BD4","description":"\u672C\u6587\u91CD\u70B9\u4ECB\u7ECD\u4E86 reComputer Super \u76F8\u8F83\u4E8E reComputer Classic \u7684\u5353\u8D8A AI \u6027\u80FD\uFF0C\u4F7F\u7528 NVIDIA Jetson Orin NX 16GB \u5C55\u73B0\u4E86\u9AD8\u8FBE 1.7 \u500D\u7684 AI \u8BA1\u7B97\u80FD\u529B\u63D0\u5347\u3002\u901A\u8FC7\u5B9E\u9645\u57FA\u51C6\u6D4B\u8BD5\uFF0C\u5305\u62EC\u4F7F\u7528 Ollama \u7684 DeepSeek-R1:7B \u6A21\u578B\u8FDB\u884C AI \u6587\u672C\u751F\u6210\uFF0C\u4EE5\u53CA\u4F7F\u7528 YOLOv11 \u76EE\u6807\u68C0\u6D4B\u6A21\u578B\u8FDB\u884C AI \u89C6\u9891\u5904\u7406\uFF0C\u7ED3\u679C\u663E\u793A reComputer Super \u63D0\u4F9B\u4E86\u663E\u8457\u66F4\u5FEB\u7684\u63A8\u7406\u901F\u5EA6\u548C\u66F4\u9AD8\u7684 GPU \u9891\u7387\u3002\u5C24\u5176\u662F\uFF0C\u5B83\u6BCF\u79D2\u5904\u7406\u7684\u56FE\u50CF\u6570\u91CF\u7EA6\u4E3A Classic \u7684 2.37 \u500D\u3002\u6587\u7AE0\u8FD8\u89E3\u91CA\u4E86\u57FA\u4E8E\u7EC8\u7AEF\u62A5\u544A\u7684 FPS \u800C\u975E\u5C4F\u5E55 FPS \u6765\u8BC4\u4F30\u6027\u80FD\u7684\u91CD\u8981\u6027\uFF0C\u56E0\u4E3A\u5C4F\u5E55 FPS \u53EF\u80FD\u53D7\u5230\u663E\u793A\u548C\u7CFB\u7EDF\u56E0\u7D20\u7684\u9650\u5236\u3002","permalink":"/cn/recomputer_jetson_super_performance"}],"unlisted":false}}')}}]);